<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { adminOperation, type Config, type Page } from '../lib/admin';
import { clone, newPlan, planError, learningStates, roleNames, type TemplatePayload, type TemplateExerciseContent } from '../lib/learning';
import PlanContentEditor from './PlanContentEditor.vue';
import Modal from './Modal.vue';
const adminApi=adminOperation();
interface Version { id:string; version_no:number; status:string; lock_version:number; payload:TemplatePayload }
interface Template { id:string; name:string; description:string; status:string; lock_version:number; versions:Version[]; published_version_id?:string|null }
interface Asset { id:string; filename?:string; original_name?:string; status:string; error_code?:string|null; byte_size?:number }
interface Role { id:string; stable_id:string; name:string; lock_version:number; payload:{body:string;allowed_mcp_ids:string[];allowed_skill_ids:string[]} }
const props=defineProps<{section:string}>();
const roles=ref<Role[]>([]),templates=ref<Template[]>([]),assets=ref<Asset[]>([]),models=ref<Config[]>([]),mcp=ref<Config[]>([]),skills=ref<Config[]>([]);
const selected=ref<Template|null>(null),version=ref<Version|null>(null),payload=ref<TemplatePayload|null>(null),role=ref<Role|null>(null),roleBody=ref(''),roleMcp=ref<string[]>([]),roleSkills=ref<string[]>([]);
const busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),creating=ref(false),newName=ref(''),newDescription=ref(''),query=ref('');
const confirmation=ref<'publish'|'offline'|'delete'|''>(''),preview=ref<{name:string;paragraphs?:any[];blocks?:any[];text?:string;next_cursor?:string|null;items?:any[]}|null>(null),previewAsset=ref('');
const savedPayload=ref(''),editName=ref(''),editDescription=ref(''),savedMetadata=ref('');
const dirty=computed(()=>!!payload.value&&(JSON.stringify(payload.value)!==savedPayload.value||JSON.stringify([editName.value,editDescription.value])!==savedMetadata.value));
const draft=computed(()=>version.value?.status==='draft');
const assetSources=computed(()=>assets.value.filter(a=>a.status==='ready'&&payload.value?.asset_ids.includes(a.id)).map(a=>({id:a.id,title:a.filename??a.original_name??'模板资料'})));
const visible=computed(()=>templates.value.filter(t=>(t.name+' '+t.description).toLowerCase().includes(query.value.toLowerCase())));
let revision=0,timer:ReturnType<typeof setTimeout>|undefined;
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请重试。';}
async function list<T>(path:string):Promise<T[]>{const items:T[]=[];let cursor:string|null=null;do{const page:Page<T>=await adminApi(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));items.push(...page.items);cursor=page.next_cursor;}while(cursor);return items;}
async function load(){const current=++revision;loading.value=true;error.value='';try{const [a,b,c,records]=await Promise.all([list<Config>('/configs/model'),list<Config>('/configs/mcp'),list<Config>('/configs/skill'),props.section==='roles'?list<Role>('/roles'):list<Template>('/agent-templates')]);if(current!==revision)return;models.value=a.filter(x=>x.enabled&&x.payload.model_kind==='generative'&&x.payload.exposed!==false);mcp.value=b.filter(x=>x.enabled);skills.value=c.filter(x=>x.enabled);if(props.section==='roles')roles.value=records as Role[];else templates.value=records as Template[];}catch(e){if(current===revision)error.value=message(e);}finally{if(current===revision)loading.value=false;}}
watch(()=>props.section,()=>{selected.value=null;role.value=null;confirmation.value='';clearTimeout(timer);void load();},{immediate:true});
async function action(run:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await run();}catch(e){error.value=message(e);}finally{busy.value=false;}}
function openRole(value:Role){role.value=clone(value);roleBody.value=value.payload.body;roleMcp.value=[...value.payload.allowed_mcp_ids];roleSkills.value=[...value.payload.allowed_skill_ids];error.value='';}
async function saveRole(){if(!role.value)return;await action(async()=>{await adminApi(`/roles/${role.value!.id}`,'PATCH',{expected_version:role.value!.lock_version,body:roleBody.value,allowed_mcp_ids:roleMcp.value,allowed_skill_ids:roleSkills.value});role.value=null;await load();notice.value='角色修订已保存，仅影响后续任务。';});}
function chooseVersion(v:Version){version.value=clone(v);const base=blankPayload();payload.value={...base,...clone(v.payload),config_choices:{...base.config_choices,...clone(v.payload?.config_choices??{})},plan:v.payload?.plan?.stages?.length?clone(v.payload.plan):base.plan};savedPayload.value=JSON.stringify(payload.value);editName.value=(v.payload as any)?.name??selected.value?.name??'';editDescription.value=(v.payload as any)?.description??selected.value?.description??'';savedMetadata.value=JSON.stringify([editName.value,editDescription.value]);confirmation.value='';}
async function openTemplate(id:string){await action(async()=>{selected.value=await adminApi<Template>(`/agent-templates/${id}`);const versions=selected.value.versions??[];const v=versions.find(v=>v.status==='draft')??versions.find(v=>v.id===selected.value!.published_version_id)??versions[0];if(v)chooseVersion(v);else{version.value=null;payload.value=null;}await loadAssets();});}
async function create(){await action(async()=>{const t=await adminApi<Template>('/agent-templates','POST',{name:newName.value,description:newDescription.value});creating.value=false;newName.value='';newDescription.value='';await load();await openTemplate(t.id);});}
async function createDraft(){if(!selected.value)return;await action(async()=>{const v=await adminApi<Version>(`/agent-templates/${selected.value!.id}/drafts`,'POST',{expected_version:selected.value!.lock_version});await openTemplate(selected.value!.id);chooseVersion(v);});}
async function loadAssets(){if(!selected.value)return;clearTimeout(timer);const id=selected.value.id;const items=await list<Asset>(`/agent-templates/${id}/assets`);if(selected.value?.id!==id)return;assets.value=items;if(items.some(a=>['queued','running','pending','processing'].includes(a.status)))timer=setTimeout(()=>void loadAssets().catch(e=>{error.value=message(e);}),2000);}
async function saveDraft(){if(!version.value||!payload.value)return;await action(async()=>{const saved=await adminApi<Version>(`/template-versions/${version.value!.id}`,'PUT',{expected_version:version.value!.lock_version,payload:payload.value,name:editName.value,description:editDescription.value});chooseVersion(saved);await load();notice.value='草稿已保存。发布前请核对完整计划、练习和资料。';});}
async function confirm(){if(!selected.value)return;await action(async()=>{const kind=confirmation.value;if(kind==='publish'){if(!payload.value||!version.value)return;const issue=planError(payload.value.plan);if(issue)throw new Error(issue);if(!payload.value.exercises.length||payload.value.exercises.some(q=>!q.question_text.trim()))throw new Error('至少一题且题干不能为空。');if(!payload.value.asset_ids.some(id=>assets.value.some(a=>a.id===id&&a.status==='ready')))throw new Error('至少选择一份处理成功的资料。');await adminApi(`/template-versions/${version.value.id}/publish`,'POST',{expected_version:version.value.lock_version});}else if(kind==='offline')await adminApi(`/agent-templates/${selected.value!.id}/offline`,'POST',{expected_version:selected.value!.lock_version});else if(kind==='delete')await adminApi(`/agent-templates/${selected.value!.id}`,'DELETE',{expected_version:selected.value!.lock_version});confirmation.value='';const id=selected.value!.id;if(kind==='delete'){selected.value=null;clearTimeout(timer);}else await openTemplate(id);await load();notice.value=kind==='publish'?'版本已发布。':kind==='offline'?'已下架，现有采用版本与资料保留。':'模板已逻辑删除，已采用的版本与资料保留。';});}
async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files??[]);input.value='';if(!files.length||!selected.value)return;await action(async()=>{const limits=await adminApi<any>('/settings');if(files.length>limits.batch_max_files)throw new Error(`每批最多 ${limits.batch_max_files} 份文件。`);if(files.some(f=>f.size>limits.file_max_bytes))throw new Error('所选文件超过平台单文件容量上限。');const body=new FormData();for(const file of files)body.append('files',file);const accepted=await adminApi<any>(`/agent-templates/${selected.value!.id}/assets`,'POST',body);const rejected:string[]=[];for(const item of accepted.items??[]){const id=item.asset?.id;if(id&&payload.value&&!payload.value.asset_ids.includes(id))payload.value.asset_ids.push(id);if(item.error)rejected.push(item.original_name??'文件');}await loadAssets();notice.value='上传已受理。请等待资料处理成功后保存草稿、发布版本。';if(rejected.length)error.value=`部分文件未受理：${rejected.join('、')}，已成功的文件保留。`;});}
async function retryAsset(a:Asset){await action(async()=>{await adminApi(`/template-assets/${a.id}/retry`,'POST',{});await loadAssets();});}
async function removeAsset(a:Asset){if(!version.value||!payload.value)return;await action(async()=>{await adminApi(`/template-versions/${version.value!.id}/assets/${a.id}`,'DELETE',{expected_version:version.value!.lock_version});payload.value!.asset_ids=payload.value!.asset_ids.filter(id=>id!==a.id);await openTemplate(selected.value!.id);});}
async function previewFile(a:Asset,append=false){await action(async()=>{const cursor=append&&preview.value?.next_cursor?'?cursor='+encodeURIComponent(preview.value.next_cursor):'';const next=await adminApi<any>(`/template-assets/${a.id}/preview${cursor}`);if(append&&preview.value)next.blocks=[...(preview.value.blocks??[]),...(next.blocks??[])];preview.value={...next,name:a.filename??a.original_name??'资料预览'};previewAsset.value=a.id;});}
function linkStage(q:TemplateExerciseContent,id:string){q.links=id?[{stage_id:id,task_id:null}]:[];}
function blankPayload():TemplatePayload{return {config_choices:{system_prompt:'',model_id:'',mcp_server_ids:[],skill_ids:[]},plan:newPlan(),exercises:[],asset_ids:[]};}
function closeTemplate(){selected.value=null;version.value=null;payload.value=null;confirmation.value='';clearTimeout(timer);}
onBeforeUnmount(()=>{++revision;clearTimeout(timer);});
</script>
<template>
<p v-if="error" class="learning-error" role="alert">{{error}} <button v-if="!busy" @click="load">重新载入列表</button></p><p v-if="notice" class="learning-success" role="status">{{notice}}</p><p v-if="loading" role="status">正在载入…</p>
<template v-if="section==='roles'"><p class="admin-notice">维护五类固定角色的职责与能力范围。主子智能体共用用户选择的模型，角色修改只影响后续受理任务。</p><div class="learning-two"><section v-for="r in roles" :key="r.id" class="learning-card"><h3>{{roleNames[r.stable_id]??r.name}}</h3><p class="learning-preview">{{r.payload.body}}</p><p class="muted">配置版本 {{r.lock_version}}</p><button @click="openRole(r)">编辑角色职责与能力</button></section></div><p v-if="!roles.length&&!loading" class="learning-empty">角色尚未初始化。请先完成版本升级初始化。</p></template>
<template v-else><div class="learning-row"><label>搜索模板 <input v-model="query" placeholder="名称或描述" /></label><button class="primary" @click="creating=true">新建模板</button><button :disabled="loading" @click="load">刷新</button></div><section v-for="t in visible" :key="t.id" class="learning-card"><div class="learning-row"><h3>{{t.name}}</h3><span>{{learningStates[t.status]??t.status}}</span><button @click="openTemplate(t.id)">管理模板与版本</button></div><p>{{t.description}}</p></section><p v-if="!visible.length&&!loading" class="learning-empty">暂无模板。新安装不预置模板，可自行创建。</p></template>
<Modal :open="creating" title="新建学习模板" @close="creating=false"><form class="learning-form" @submit.prevent="create"><label>模板名称<input v-model="newName" required maxlength="50" /></label><label>模板描述<textarea v-model="newDescription" rows="3" maxlength="500" /></label><p v-if="error" class="learning-error" role="alert">{{error}}</p><button class="primary" :disabled="busy">创建草稿</button></form></Modal>
<Modal :open="!!role" title="编辑固定子智能体" wide @close="role=null"><form v-if="role" class="learning-form" @submit.prevent="saveRole"><h3>{{roleNames[role.stable_id]??role.name}}</h3><label>职责提示词<textarea v-model="roleBody" rows="10" required maxlength="10000" /></label><fieldset><legend>允许的MCP扩展</legend><label v-for="s in mcp" :key="s.id" class="check-row"><input v-model="roleMcp" type="checkbox" :value="s.stable_id" />{{s.name}}</label><label v-for="id in roleMcp.filter(id=>!mcp.some(s=>s.stable_id===id))" :key="id" class="check-row"><input v-model="roleMcp" type="checkbox" :value="id" />不可用MCP {{id}}（取消以清理授权）</label></fieldset><fieldset><legend>允许的技能</legend><label v-for="s in skills" :key="s.id" class="check-row"><input v-model="roleSkills" type="checkbox" :value="s.stable_id" />{{s.name}}</label><label v-for="id in roleSkills.filter(id=>!skills.some(s=>s.stable_id===id))" :key="id" class="check-row"><input v-model="roleSkills" type="checkbox" :value="id" />不可用技能 {{id}}（取消以清理授权）</label></fieldset><p class="muted">实际范围取平台开放、角色允许与个人开启的交集。每消息仍只显式加载一项技能。</p><p v-if="error" class="learning-error" role="alert">{{error}}</p><div class="learning-actions"><button class="primary" :disabled="busy">保存角色修订</button><button type="button" :disabled="busy" @click="role=null">取消</button></div></form></Modal>
<Modal :open="!!selected" :title="selected?.name??'模板管理'" wide @close="closeTemplate">
<template v-if="selected"><p>{{selected.description}}</p><div class="learning-row"><label>版本 <select :value="version?.id" :disabled="busy" @change="chooseVersion(selected!.versions.find(v=>v.id===($event.target as HTMLSelectElement).value)!)"><option v-for="v in selected.versions" :key="v.id" :value="v.id">v{{v.version_no}} · {{learningStates[v.status]??v.status}}</option></select></label><button :disabled="busy||selected.status==='deleted'" @click="createDraft">从当前版本创建草稿</button></div><p v-if="!draft" class="learning-message">已发布内容固定保存。修改请创建新草稿，现有个人副本不会跟随更新。</p>
<form v-if="payload" class="learning-form" novalidate @submit.prevent="saveDraft"><fieldset :disabled="!draft||busy"><label>模板名称<input v-model="editName" required maxlength="50" /></label><label>模板描述<textarea v-model="editDescription" rows="3" maxlength="500" /></label><h3>智能体配置</h3><label>系统提示词<textarea v-model="payload.config_choices.system_prompt" rows="6" maxlength="10000" /></label><label>生成模型<select v-model="payload.config_choices.model_id" aria-label="生成模型"><option value="">请选择</option><option v-if="payload.config_choices.model_id&&!models.some(m=>m.stable_id===payload!.config_choices.model_id)" :value="payload.config_choices.model_id">原模型不可用，请选择替代</option><option v-for="m in models" :key="m.id" :value="m.stable_id">{{m.name}}</option></select></label><div class="learning-two"><fieldset><legend>开启MCP扩展</legend><label v-for="s in mcp" :key="s.id" class="check-row"><input v-model="payload.config_choices.mcp_server_ids" type="checkbox" :value="s.stable_id" />{{s.name}}</label></fieldset><fieldset><legend>开启技能</legend><label v-for="s in skills" :key="s.id" class="check-row"><input v-model="payload.config_choices.skill_ids" type="checkbox" :value="s.stable_id" />{{s.name}}</label></fieldset></div><h3>完整学习计划</h3><PlanContentEditor :value="payload.plan" show-title :sources="assetSources" :disabled="!draft||busy"/><h3>练习</h3><section v-for="(q,i) in payload.exercises" :key="i" class="learning-card"><label>题目 {{i+1}}<textarea v-model="q.question_text" rows="4" /></label><label>关联阶段（可选）<select :value="q.links?.[0]?.stage_id??''" @change="linkStage(q,($event.target as HTMLSelectElement).value)"><option value="">独立练习</option><option v-for="s in payload.plan.stages" :key="s.id" :value="s.id">{{s.title||'未命名阶段'}}</option></select></label><label v-if="q.links?.[0]?.stage_id">关联任务（可选）<select v-model="q.links[0]!.task_id"><option :value="null">整个阶段</option><option v-for="t in payload.plan.stages.find(s=>s.id===q.links[0]?.stage_id)?.tasks??[]" :key="t.id" :value="t.id">{{t.title||'未命名任务'}}</option></select></label><label>模板预置答案（可选）<textarea v-model="q.answer_text" rows="3" /></label><label>解析（可选）<textarea v-model="q.explanation" rows="3" /></label><label>题目来源<select v-model="q.provenance"><option value="generated">AI生成题 / 模板编写</option><option value="original">资料原题</option><option value="adapted">改编题</option></select></label><fieldset v-if="assetSources.length"><legend>题目资料来源</legend><label v-for="source in assetSources" :key="source.id" class="check-row"><input v-model="q.source_ids" type="checkbox" :value="source.id" />{{source.title}}</label></fieldset><button type="button" @click="payload.exercises.splice(i,1)">删除题目</button></section><button type="button" @click="payload.exercises.push({question_text:'',answer_text:null,explanation:null,provenance:'generated',source_ids:[],links:[]})">添加练习</button><h3>版本资料清单</h3><label v-for="a in assets" :key="a.id" class="check-row"><input v-model="payload.asset_ids" type="checkbox" :value="a.id" />{{a.filename??a.original_name}} · {{learningStates[a.status]??a.status}}</label></fieldset><p v-if="error" class="learning-error" role="alert">{{error}}</p><p v-if="notice" class="learning-success" role="status">{{notice}}</p><p v-if="dirty" class="muted">有未保存修改。请先保存草稿再发布。</p><div v-if="draft" class="learning-actions"><button class="primary" :disabled="busy">保存草稿</button><button type="button" :disabled="busy||dirty" @click="confirmation='publish'">发布已保存版本</button><button type="button" :disabled="busy" @click="chooseVersion(version!)">放弃未保存修改</button></div></form>
<button v-if="!payload&&draft" @click="payload=blankPayload()">填写草稿内容</button><section class="learning-card"><div class="learning-row"><h3>专属资料</h3><button :disabled="busy" @click="loadAssets">刷新处理状态</button></div><p class="muted">仅管理本模板资料。已发布版本引用的资料不会因草稿解除而删除。</p><label v-if="draft">上传文字资料 <input type="file" accept=".txt,.pdf,.docx" multiple :disabled="busy" @change="upload" /></label><div v-for="a in assets" :key="a.id" class="learning-row"><span>{{a.filename??a.original_name}} · {{learningStates[a.status]??a.status}} {{a.error_code??''}}</span><button v-if="a.status==='ready'" :disabled="busy" @click="previewFile(a)">文字预览</button><button v-if="a.status==='failed'" :disabled="busy" @click="retryAsset(a)">重试处理</button><button v-if="draft&&payload?.asset_ids.includes(a.id)" :disabled="busy" @click="removeAsset(a)">从草稿解除</button></div></section><div class="learning-actions"><button v-if="selected.status!=='deleted'" :disabled="busy" @click="confirmation='offline'">下架模板</button><button v-if="selected.status!=='deleted'" :disabled="busy" @click="confirmation='delete'">逻辑删除模板</button></div><div v-if="confirmation" class="learning-message"><p>{{confirmation==='publish'?'将发布数据库中已保存的草稿内容。请先保存本次编辑，再发布。':confirmation==='offline'?'下架后停止新采用，已有版本与资料保留。':'逻辑删除后停止新采用，保留历史版本及已采用资料。'}}确认操作？</p><button :disabled="busy" @click="confirm">确认{{confirmation==='publish'?'发布':confirmation==='offline'?'下架':'删除'}}</button> <button :disabled="busy" @click="confirmation=''">取消</button></div></template>
</Modal>
<Modal :open="!!preview" :title="preview?.name??'资料预览'" wide @close="preview=null"><template v-if="preview"><p v-if="preview.text" class="learning-preview">{{preview.text}}</p><p v-for="(p,i) in preview.blocks??preview.paragraphs??preview.items??[]" :key="i" class="learning-preview">{{typeof p==='string'?p:p.text??p.content}}</p><button v-if="preview.next_cursor" :disabled="busy" @click="previewFile(assets.find(a=>a.id===previewAsset)!,true)">继续读取</button></template></Modal>
</template>
